mapper.select:
SELECT id, parent_dept_no, dept_no, dept_name, sort_no, data_state, create_time, update_time, create_by, update_by, leader_id, remark FROM `sys_dept`
AND parent_dept_no = #{parentDeptNo}
AND dept_name LIKE CONCAT('%', #{deptName}, '%')
AND data_state = #{dataStatus}
ORDER BY sort_no ASC, id ASC

SELECT id, parent_dept_no, dept_no, dept_name, sort_no, data_state,
       create_time, update_time, create_by, update_by, leader_id, remark
FROM sys_dept WHERE id = #{id}

SELECT id, parent_dept_no, dept_no, dept_name, sort_no, data_state,
       create_time, update_time, create_by, update_by, leader_id, remark
FROM sys_dept WHERE parent_dept_no = #{parentDeptNo}
